CREATE TABLE IF NOT EXISTS component_damage_rules(equipment_type TEXT NOT NULL,component_code TEXT NOT NULL,damage_code TEXT NOT NULL,standard_version TEXT NOT NULL,source_reference TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),PRIMARY KEY(equipment_type,component_code,damage_code,standard_version));
CREATE INDEX IF NOT EXISTS idx_component_damage_lookup ON component_damage_rules(equipment_type,component_code,active);
DELETE FROM component_damage_rules WHERE equipment_type='GP' AND component_code='PAA';
INSERT INTO component_damage_rules(equipment_type,component_code,damage_code,standard_version,source_reference,active)
